import type { Metadata } from "next";
import { EditStrategyScreen } from "@/features/strategies/builder/StrategyBuilderScreens";

export const metadata: Metadata = { title: "Edit strategy" };

// Same shape as PageProps<"/strategies/[id]/edit"> (route types are generated by `next typegen`).
export default async function Page({ params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  return <EditStrategyScreen id={id} />;
}
